(function(){"use strict";const e=document.querySelectorAll(".faq__item");if(!e.length)return;e.forEach(t=>{const n=t.querySelector(".faq__question"),s=t.querySelector(".faq__answer");if(!n||!s)return;n.addEventListener("click",()=>{const o=n.getAttribute("aria-expanded")==="true";e.forEach(e=>{if(e!==t){const n=e.querySelector(".faq__question"),t=e.querySelector(".faq__answer");n&&t&&(n.setAttribute("aria-expanded","false"),t.style.maxHeight="",t.classList.remove("faq__answer--open"),e.classList.remove("faq__item--open"))}}),n.setAttribute("aria-expanded",!o),o?(s.style.maxHeight="",s.classList.remove("faq__answer--open")):(s.style.maxHeight=s.scrollHeight+"px",s.classList.add("faq__answer--open")),t.classList.toggle("faq__item--open",!o)}),n.addEventListener("keydown",e=>{const t=Array.from(document.querySelectorAll(".faq__question")),s=t.indexOf(n);switch(e.key){case"ArrowDown":e.preventDefault(),s<t.length-1&&t[s+1].focus();break;case"ArrowUp":e.preventDefault(),s>0&&t[s-1].focus();break;case"Home":e.preventDefault(),t[0].focus();break;case"End":e.preventDefault(),t[t.length-1].focus();break}})})})()